public class Main {
  static int process(int[] arr, int idx) {
    if (idx >= arr.length) {
      return 0;
    }
    int current = arr[idx];
    if (current % 3 == 0) {
      arr[idx] = current * 2;
    } else {
      arr[idx] = current + 1;
    }
    return arr[idx] + process(arr, idx + 1);
  }

  public static void main(String[] args) {
    int[] numbers = {1, 2, 3, 4, 5, 6};
    int sum = process(numbers, 0);
    for (int i = 0; i < numbers.length; i++) {
      System.out.print(numbers[i] + " ");
    }
    System.out.println();
    System.out.println(sum);
  }
}

